import { createHash } from 'node:crypto';
import { expect, test } from '@playwright/test';
import type { Page } from '@playwright/test';
import { assertViewportRaster, viewportTiles } from './viewportRaster';

/** Capture every main-content pixel through actual painted viewports, never an oversized full-page texture. */
export async function captureReadiness(page: Page): Promise<string> {
  const viewport = page.viewportSize();
  if (!viewport) throw new Error('Readiness verification requires the configured viewport.');
  await page.evaluate(() => window.scrollTo(0, 0));
  await page.evaluate(
    () =>
      new Promise<void>((resolve) =>
        requestAnimationFrame(() => requestAnimationFrame(() => resolve())),
      ),
  );
  const shellImage = await page.screenshot({
    animations: 'disabled',
    caret: 'hide',
    scale: 'css',
    fullPage: false,
  });
  assertViewportRaster(shellImage, viewport.width, viewport.height);
  await test
    .info()
    .attach('readiness-shell-viewport', { body: shellImage, contentType: 'image/png' });
  const shell = createHash('sha256').update(shellImage).digest('hex');
  const main = page.locator('main');
  const rect = await main.evaluate((element) => {
    const r = element.getBoundingClientRect();
    return {
      x: Math.floor(r.x),
      top: Math.floor(r.y + window.scrollY),
      width: Math.ceil(r.right) - Math.floor(r.x),
      height: Math.ceil(r.bottom + window.scrollY) - Math.floor(r.y + window.scrollY),
    };
  });
  const inset = await page.locator('header').evaluateAll((headers) =>
    Math.ceil(
      Math.max(
        0,
        ...headers.map((header) => {
          const r = header.getBoundingClientRect();
          return ['sticky', 'fixed'].includes(getComputedStyle(header).position) &&
            r.top <= 0 &&
            r.bottom > 0
            ? r.bottom
            : 0;
        }),
      ),
    ),
  );
  const tiles = viewportTiles(rect.top, rect.height, viewport.height - inset - 1);
  const captures: { top: number; height: number; sha256: string }[] = [];
  for (const [index, tile] of tiles.entries()) {
    await page.evaluate((y) => window.scrollTo(0, y), tile.top - inset);
    await page.evaluate(
      () =>
        new Promise<void>((resolve) =>
          requestAnimationFrame(() => requestAnimationFrame(() => resolve())),
        ),
    );
    const y = tile.top - (await page.evaluate(() => window.scrollY));
    expect(y, 'Tile must not be covered by a sticky header').toBeGreaterThanOrEqual(inset);
    expect(y + tile.height, 'Every tile must fit the actual viewport').toBeLessThanOrEqual(
      viewport.height,
    );
    const screenshot = await page.screenshot({
      animations: 'disabled',
      caret: 'hide',
      scale: 'css',
      fullPage: false,
      clip: { x: rect.x, y, width: rect.width, height: tile.height },
    });
    assertViewportRaster(screenshot, rect.width, tile.height);
    await test
      .info()
      .attach(`readiness-tile-${String(index + 1).padStart(2, '0')}`, {
        body: screenshot,
        contentType: 'image/png',
      });
    captures.push({ ...tile, sha256: createHash('sha256').update(screenshot).digest('hex') });
  }
  const end = await main.evaluate((element) => {
    const r = element.getBoundingClientRect();
    return {
      x: Math.floor(r.x),
      top: Math.floor(r.y + window.scrollY),
      width: Math.ceil(r.right) - Math.floor(r.x),
      height: Math.ceil(r.bottom + window.scrollY) - Math.floor(r.y + window.scrollY),
    };
  });
  expect(end, 'Layout must stay fixed while all pixels are captured').toEqual(rect);
  expect(page.viewportSize(), 'Do not resize or scale the tested viewport').toEqual(viewport);
  const manifest = { viewport, shell, rect, tiles: captures };
  await test
    .info()
    .attach('readiness-capture-coverage', {
      body: JSON.stringify(manifest, null, 2),
      contentType: 'application/json',
    });
  return createHash('sha256').update(JSON.stringify(manifest)).digest('hex');
}

import { inflateSync } from 'node:zlib';

/** Contiguous source intervals, never a sampled set of screenshots. */
export function viewportTiles(
  top: number,
  height: number,
  available: number,
): { top: number; height: number }[] {
  if (
    ![top, height, available].every(Number.isSafeInteger) ||
    top < 0 ||
    height < 1 ||
    available < 1 ||
    height > 100_000
  ) {
    throw new Error('Invalid or excessive readiness capture dimensions.');
  }
  const result: { top: number; height: number }[] = [];
  for (let offset = 0; offset < height; offset += available) {
    result.push({ top: top + offset, height: Math.min(available, height - offset) });
  }
  return result;
}

/** Fail if Chromium returns a clipped or single-background raster for populated content. */
export function assertViewportRaster(png: Buffer, width: number, height: number): void {
  if (
    !png.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])) ||
    png.length < 33
  ) {
    throw new Error('Readiness capture is not PNG.');
  }
  if (
    png.readUInt32BE(16) !== width ||
    png.readUInt32BE(20) !== height ||
    width < 1 ||
    height < 1 ||
    width * height > 4_000_000
  ) {
    throw new Error('Readiness raster dimensions do not match the bounded viewport tile.');
  }
  const channels = png[25] === 2 ? 3 : png[25] === 6 ? 4 : 0;
  if (png[24] !== 8 || !channels || png[26] !== 0 || png[27] !== 0 || png[28] !== 0) {
    throw new Error('Unsupported readiness PNG format.');
  }
  const chunks: Buffer[] = [];
  for (let offset = 8; offset + 12 <= png.length;) {
    const size = png.readUInt32BE(offset);
    if (offset + size + 12 > png.length) throw new Error('Truncated readiness PNG.');
    if (png.toString('ascii', offset + 4, offset + 8) === 'IDAT')
      chunks.push(png.subarray(offset + 8, offset + 8 + size));
    offset += size + 12;
  }
  const stride = width * channels;
  const expected = (stride + 1) * height;
  const bytes = inflateSync(Buffer.concat(chunks), { maxOutputLength: expected });
  if (bytes.length !== expected) throw new Error('Readiness raster data is incomplete.');
  let previous = Buffer.alloc(stride);
  let first: number[] | null = null;
  for (let y = 0; y < height; y++) {
    const filter = bytes[y * (stride + 1)];
    if (filter > 4) throw new Error('Unsupported readiness PNG row filter.');
    const row = Buffer.alloc(stride);
    for (let x = 0; x < stride; x++) {
      const left = x >= channels ? row[x - channels] : 0;
      const up = previous[x];
      const corner = x >= channels ? previous[x - channels] : 0;
      let delta = 0;
      if (filter === 1) delta = left;
      else if (filter === 2) delta = up;
      else if (filter === 3) delta = Math.floor((left + up) / 2);
      else if (filter === 4) {
        const prediction = left + up - corner;
        const a = Math.abs(prediction - left),
          b = Math.abs(prediction - up),
          c = Math.abs(prediction - corner);
        delta = a <= b && a <= c ? left : b <= c ? up : corner;
      }
      row[x] = (bytes[y * (stride + 1) + 1 + x] + delta) & 255;
    }
    for (let x = 0; x < stride; x += channels) {
      first ??= [row[x], row[x + 1], row[x + 2]];
      if (row[x] !== first[0] || row[x + 1] !== first[1] || row[x + 2] !== first[2]) return;
    }
    previous = row;
  }
  throw new Error('Populated readiness tile rendered as a single background color.');
}

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { deflateSync } from 'node:zlib';
import test from 'node:test';
import { assertViewportRaster, viewportTiles } from '../Support/viewportRaster.ts';

const fixtures: { format: string; filter: number; base64: string }[] = JSON.parse(
  readFileSync(new URL('../Fixtures/viewport-raster.json', import.meta.url), 'utf8'),
);
for (const fixture of fixtures) {
  test(`${fixture.format} row filter ${fixture.filter} preserves a populated bounded raster`, () => {
    const png = Buffer.from(fixture.base64, 'base64');
    assert.doesNotThrow(() => assertViewportRaster(png, 3, 2));
    assert.throws(() => assertViewportRaster(png, 3, 3), /dimensions/);
  });
}

test('every vertical source pixel is captured exactly once, including a short final tile', () => {
  const tiles = viewportTiles(84, 28587, 779);
  assert.equal(tiles[0].top, 84);
  let cursor = 84;
  for (const tile of tiles) {
    assert.equal(tile.top, cursor);
    assert.ok(tile.height > 0 && tile.height <= 779);
    cursor += tile.height;
  }
  assert.equal(cursor, 84 + 28587);
  assert.equal(tiles.at(-1)!.height, 543);
});

test('empty, unsafe and unbounded screenshot dimensions cannot pass', () => {
  for (const values of [
    [-1, 40, 30],
    [1, 0, 30],
    [1, 40, 0],
    [1, 100001, 40],
    [1, 2.5, 1],
  ]) {
    assert.throws(() => viewportTiles(values[0], values[1], values[2]), /dimensions/);
  }
  assert.throws(() => assertViewportRaster(Buffer.from('not png'), 3, 2), /not PNG/);
});

test('a solid-color raster is not accepted as populated readiness content', () => {
  // Real PNG header; replace only image data with two unfiltered uniform RGB rows.
  const original = Buffer.from(fixtures[0].base64, 'base64');
  const compressed = deflateSync(Buffer.from([0, ...Array(9).fill(18), 0, ...Array(9).fill(18)]));
  const idat = Buffer.alloc(12 + compressed.length);
  idat.writeUInt32BE(compressed.length);
  idat.write('IDAT', 4);
  compressed.copy(idat, 8);
  const png = Buffer.concat([original.subarray(0, 33), idat, original.subarray(-12)]);
  assert.throws(() => assertViewportRaster(png, 3, 2), /single background color/);
});
